import sqlite3,json,sys
c=sqlite3.connect(sys.argv[1])
print(c.execute("select name,count(*) from events group by 1").fetchall())
print(c.execute("select platform,is_test,count(*) from users group by 1,2").fetchall())
print(c.execute("select min(ts),max(ts),min(length(ts)),max(length(ts)) from events").fetchall())
S=['install','tutorial_complete','first_match','purchase']
u={r[0]:r[1].strip().lower() for r in c.execute("select user_id,platform from users where is_test=0")}
ev={}
for uid,n,ts in c.execute("select user_id,trim(lower(name)),ts from events"):
  if uid in u: ev.setdefault(uid,[]).append((ts,n))
F={};B={}
for uid,p in u.items():
  F.setdefault(p,[0]*4); t=None
  for i,s in enumerate(S):
    ts=[x for x,n in ev.get(uid,[]) if n==s and (t is None or x>=t)]
    if not ts: break
    t=min(ts); F[p][i]+=1
for p,f in F.items():
  conv={S[i]:f[i]/f[i-1] if f[i-1] else 0 for i in range(1,4)}; B[p]=min(conv,key=conv.get); print(p,f,conv)
json.dump({"funnel":{p:dict(zip(S,f)) for p,f in F.items()},"biggest_drop":B},open('result.json','w'),indent=2)
